"""Collect results/*/summary.json into results/SUMMARY.md."""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / "results"


def fmt(x, nd=3):
    return "–" if x is None else (f"{x:.{nd}f}" if isinstance(x, float) else str(x))


def main() -> None:
    runs = sorted(p for p in ROOT.iterdir() if (p / "summary.json").exists())
    lines = [
        "# Results summary",
        "",
        "Generated by `scripts/summarize_results.py` from `results/*/summary.json`. "
        "Do not edit by hand; rerun `scripts/reproduce.sh`.",
        "",
        "| run | docs (A/B) | kNN same-label (chance) | segregation index, median of 120 settings | "
        "bridge nodes, median | v2-rule bridge nodes, median | coverage | persistent bridge docs (A/B) | "
        "of A, off-topic |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    detail = []
    for run in runs:
        s = json.loads((run / "summary.json").read_text())
        an, knn, grid, per = s["analysed"], s["knn_segregation"], s["grid"], s["persistence"]
        off = s["controls"].get("field_a_off_topic_in_bridges")
        off_txt = "–" if off is None else f"{off['table'][0][0]}/{per['docs_field_a']} (p={off['p']:.3g})"
        lines.append(
            f"| `{run.name}` | {an['n']} ({an['field_a']}/{an['field_b']}) | "
            f"{knn['observed_same_label']:.3f} ({knn['null_mean']:.3f}) | "
            f"{grid['segregation_index_median']:.3f} | {fmt(grid['bridge_nodes_median'], 1)} | "
            f"{fmt(grid['legacy_bridge_nodes_median'], 1)} | {grid['coverage_median']:.2f} | "
            f"{per['docs']} ({per['docs_field_a']}/{per['docs_field_b']}) | {off_txt} |")
        detail.append(f"\n## `{run.name}`\n")
        a = s["args"]
        detail.append(f"representation={a['representation']}, subset={a['subset']}, "
                      f"eps quantile={a['eps_quantile']} (eps={s['dbscan']['eps']:.3f}), "
                      f"min_balance={s['criteria']['min_balance']}, min_per_field={s['criteria']['min_per_field']}, "
                      f"persistence={s['persistence_threshold']}\n")
        if "cosine" in s:
            c = s["cosine"]
            detail.append(f"Cosine: closest cross-field pair {c['cross_field_max']:.3f}; median cross-field "
                          f"{c['cross_field_median']:.3f}; median within Field A {c['within_a_median']:.3f}.\n")
        if "legacy_check" in s:
            lc = s["legacy_check"]
            detail.append(f"v2 graph rebuilt (n_cubes=20, overlap=0.6, eps=0.5): {lc['nodes']} nodes, "
                          f"{lc['legacy_bridge_nodes']} v2-rule bridge nodes, mean mixing "
                          f"{lc['legacy_mean_mixing']:.3f} (v2 reported 235 / 140 / 0.222). "
                          f"Same statistics with labels shuffled on the same graph: "
                          f"{lc['legacy_null_bridge_nodes_mean']:.1f} bridge nodes (minimum "
                          f"{lc['legacy_null_bridge_nodes_min']:.0f}), mean mixing "
                          f"{lc['legacy_null_mean_mixing']:.3f}.\n")
        for g in s["bridge_groups"]:
            terms = ", ".join(t for t, _ in g["distinctive_terms"][:8])
            detail.append(f"- Bridge group: {g['size']} docs (A {g['field_a']}, B {g['field_b']}), "
                          f"on-topic share {g['on_topic_share']:.2f}; terms: {terms}")
            for t in g["titles"]:
                detail.append(f"  - {t}")
    (ROOT / "SUMMARY.md").write_text("\n".join(lines + detail) + "\n")
    print("\n".join(lines))


if __name__ == "__main__":
    main()
